//! Rust source for the configured types (ADR 0016).
//!
//! The output is a pure function of the proto, its SHA-256 and the
//! configuration: no timestamps, no map iteration order (every map is a
//! `BTreeMap`, every list follows the proto), so `--check` can compare bytes.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use crate::config::{Config, FieldConfig};
use crate::proto::{Enum, Field, FieldType, Message, PACKAGE, Schema};

/// The generated files, by path relative to `src/generated/`.
pub fn emit(
    schema: &Schema,
    config: &Config,
    proto_sha256: &str,
) -> Result<BTreeMap<String, String>, String> {
    let mut modules: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for e in &schema.enums {
        if let Some(ec) = config.enums.get(&e.name) {
            let (module, _) = split_path(config, &e.name)?;
            modules
                .entry(module)
                .or_default()
                .push(emit_enum(e, ec, config)?);
        }
    }
    for m in &schema.messages {
        if let Some(mc) = config.messages.get(&m.name) {
            let (module, _) = split_path(config, &m.name)?;
            modules
                .entry(module)
                .or_default()
                .push(emit_message(m, mc, config)?);
        }
    }

    let header = format!(
        "// @generated by tools/a2a-codegen from proto/a2a_v1/a2a.proto,\n\
         // sha256 {proto_sha256}.\n\
         // Do not edit: change the proto or crates/a2a-protocol-types/codegen.toml\n\
         // and regenerate (ADR 0016).\n"
    );
    let mut files = BTreeMap::new();
    let licence = "// SPDX-License-Identifier: Apache-2.0\n\
                   // Copyright 2026 Tom F. <tomf@tomtomtech.net> (https://github.com/tomtom215)\n";
    let mut root = format!(
        "{licence}{header}\n\
         //! The public types generated from `a2a.proto` (ADR 0016). Each is\n\
         //! re-exported from the module that documents it, which keeps its\n\
         //! `impl` blocks.\n\n"
    );
    for (module, items) in &modules {
        let _ = writeln!(root, "pub mod {module};");
        let mut file = format!("{licence}{header}\n");
        file.push_str("use serde::{Deserialize, Serialize};\n\n");
        file.push_str(&items.join("\n"));
        files.insert(format!("{module}.rs"), rustfmt(&file)?);
    }
    files.insert("mod.rs".to_owned(), rustfmt(&root)?);
    Ok(files)
}

/// `task::Task` as (`task`, `Task`); a nested path's modules are joined
/// with `_` into one generated file.
fn split_path(config: &Config, proto_name: &str) -> Result<(String, String), String> {
    let path = config
        .paths
        .get(proto_name)
        .ok_or_else(|| format!("[paths] has no entry for {proto_name}"))?;
    let (module, name) = path
        .rsplit_once("::")
        .ok_or_else(|| format!("[paths] {proto_name} = {path:?} names no module"))?;
    Ok((module.replace("::", "_"), name.to_owned()))
}

fn rust_name(config: &Config, proto_name: &str) -> Result<String, String> {
    split_path(config, proto_name).map(|(_, name)| name)
}

fn emit_enum(e: &Enum, ec: &crate::config::EnumConfig, config: &Config) -> Result<String, String> {
    let name = rust_name(config, &e.name)?;
    let mut out = doc(
        &e.name,
        &e.comment,
        ec.doc.as_deref(),
        ec.doc_append.as_deref(),
        0,
    )?;
    let _ = writeln!(out, "#[derive({})]", ec.derives.join(", "));
    for attr in &ec.attrs {
        let _ = writeln!(out, "{attr}");
    }
    let _ = writeln!(out, "pub enum {name} {{");
    let prefix = format!("{}_", screaming(&e.name));
    for v in &e.values {
        let vc = ec.values.get(&v.name);
        let variant = pascal(
            v.name
                .strip_prefix(&prefix)
                .ok_or_else(|| format!("{}.{} does not start with {prefix}", e.name, v.name))?,
        );
        out.push_str(&doc(
            &format!("{}.{}", e.name, v.name),
            &v.comment,
            vc.and_then(|c| c.doc.as_deref()),
            vc.and_then(|c| c.doc_append.as_deref()),
            1,
        )?);
        let mut serde = vec![format!("rename = {:?}", v.name)];
        for alias in vc.map(|c| c.aliases.as_slice()).unwrap_or_default() {
            serde.push(format!("alias = {alias:?}"));
        }
        let _ = writeln!(out, "    #[serde({})]", serde.join(", "));
        // The discriminant is the proto number, so `as i32` agrees with the
        // prost enum whatever order the proto declares its values in.
        let _ = writeln!(out, "    {variant} = {},", v.number);
    }
    out.push_str("}\n");
    Ok(out)
}

fn emit_message(
    m: &Message,
    mc: &crate::config::MessageConfig,
    config: &Config,
) -> Result<String, String> {
    if !m.oneofs.is_empty() {
        return Err(format!(
            "{}: oneofs are not generated yet; keep it [pending]",
            m.name
        ));
    }
    let name = rust_name(config, &m.name)?;
    let mut out = doc(
        &m.name,
        &m.comment,
        mc.doc.as_deref(),
        mc.doc_append.as_deref(),
        0,
    )?;
    let _ = writeln!(out, "#[derive({})]", mc.derives.join(", "));
    out.push_str("#[serde(rename_all = \"camelCase\")]\n");
    for attr in &mc.attrs {
        let _ = writeln!(out, "{attr}");
    }
    let _ = writeln!(out, "pub struct {name} {{");
    let default = FieldConfig::default();
    for f in &m.fields {
        let fc = mc.fields.get(&f.name).unwrap_or(&default);
        let field_name = fc.rename.clone().unwrap_or_else(|| f.name.clone());
        let ty = match &fc.ty {
            Some(ty) => ty.clone(),
            None => {
                default_type(f, config).map_err(|why| format!("{}.{}: {why}", m.name, f.name))?
            }
        };
        out.push_str(&doc(
            &format!("{}.{}", m.name, f.name),
            &f.comment,
            fc.doc.as_deref(),
            fc.doc_append.as_deref(),
            1,
        )?);
        let mut serde = Vec::new();
        if camel(&field_name) != f.json_name {
            serde.push(format!("rename = {:?}", f.json_name));
        }
        for alias in &fc.aliases {
            serde.push(format!("alias = {alias:?}"));
        }
        let explicit_skip = fc
            .serde
            .iter()
            .any(|s| s.starts_with("skip_serializing_if"));
        if ty.starts_with("Option<") && !explicit_skip {
            serde.push("skip_serializing_if = \"Option::is_none\"".to_owned());
        }
        serde.extend(fc.serde.iter().cloned());
        if !serde.is_empty() {
            let _ = writeln!(out, "    #[serde({})]", serde.join(", "));
        }
        let _ = writeln!(out, "    pub {field_name}: {ty},");
    }
    out.push_str("}\n");
    Ok(out)
}

/// The default translation of a field's type (ADR 0016's table).
fn default_type(f: &Field, config: &Config) -> Result<String, String> {
    if f.map_key.is_some() {
        return Err("a map field needs an explicit `type`".to_owned());
    }
    let base = match &f.ty {
        FieldType::String => "String".to_owned(),
        FieldType::Bool => "bool".to_owned(),
        FieldType::I32 => "i32".to_owned(),
        FieldType::I64 => "i64".to_owned(),
        FieldType::U32 => "u32".to_owned(),
        FieldType::U64 => "u64".to_owned(),
        FieldType::F32 => "f32".to_owned(),
        FieldType::F64 => "f64".to_owned(),
        FieldType::Bytes => return Err("a bytes field needs an explicit `type`".to_owned()),
        FieldType::Message(full) => match full.as_str() {
            "google.protobuf.Struct" | "google.protobuf.Value" => "serde_json::Value".to_owned(),
            "google.protobuf.Timestamp" => "String".to_owned(),
            other => crate_path(other, config)?,
        },
        FieldType::Enum(full) => crate_path(full, config)?,
    };
    let ty = if f.repeated {
        format!("Vec<{base}>")
    } else {
        base
    };
    Ok(if f.required {
        ty
    } else {
        format!("Option<{ty}>")
    })
}

fn crate_path(full_name: &str, config: &Config) -> Result<String, String> {
    let name = full_name
        .strip_prefix(PACKAGE)
        .and_then(|s| s.strip_prefix('.'))
        .ok_or_else(|| format!("{full_name} is outside {PACKAGE}; give the field a `type`"))?;
    let path = config
        .paths
        .get(name)
        .ok_or_else(|| format!("[paths] has no entry for {name}"))?;
    Ok(format!("crate::{path}"))
}

/// The doc comment: `doc`, or the proto comment, then `append`; refused when
/// both are empty, since every public item is documented.
fn doc(
    what: &str,
    comment: &str,
    doc: Option<&str>,
    append: Option<&str>,
    indent: usize,
) -> Result<String, String> {
    let mut text = match doc {
        Some(doc) => doc.trim().to_owned(),
        None => escape(comment),
    };
    if let Some(append) = append {
        if !text.is_empty() {
            text.push_str("\n\n");
        }
        text.push_str(append.trim());
    }
    if text.is_empty() {
        return Err(format!("{what} has no proto comment; give it a `doc`"));
    }
    let pad = "    ".repeat(indent);
    let mut out = String::new();
    for line in text.lines() {
        if line.is_empty() {
            let _ = writeln!(out, "{pad}///");
        } else {
            let _ = writeln!(out, "{pad}/// {line}");
        }
    }
    Ok(out)
}

/// A proto comment as Markdown that reads as it was written: outside code
/// spans, brackets and angle brackets are escaped, so rustdoc takes them for
/// neither links nor HTML, and a URL (with any quotes around it) becomes a
/// code span, since the proto's URLs are examples rather than links.
fn escape(comment: &str) -> String {
    comment
        .lines()
        .map(escape_line)
        .collect::<Vec<_>>()
        .join("\n")
}

fn escape_line(line: &str) -> String {
    let mut out = String::with_capacity(line.len());
    let mut in_code = false;
    for (i, word) in line.split(' ').enumerate() {
        if i > 0 {
            out.push(' ');
        }
        let ticks = word.matches('`').count();
        if !in_code && ticks == 0 && word.contains("://") {
            let end = word.trim_end_matches([',', '.', ';', ')']);
            let _ = write!(out, "`{end}`{}", &word[end.len()..]);
            continue;
        }
        for c in word.chars() {
            if c == '`' {
                in_code = !in_code;
            }
            if !in_code && matches!(c, '[' | ']' | '<' | '>') {
                out.push('\\');
            }
            out.push(c);
        }
    }
    out
}

/// `TaskState` as `TASK_STATE`.
fn screaming(name: &str) -> String {
    let mut out = String::new();
    for (i, c) in name.chars().enumerate() {
        if c.is_ascii_uppercase() && i > 0 {
            out.push('_');
        }
        out.push(c.to_ascii_uppercase());
    }
    out
}

/// `INPUT_REQUIRED` as `InputRequired`.
fn pascal(screaming: &str) -> String {
    screaming
        .split('_')
        .map(|w| {
            let mut c = w.chars();
            c.next().map_or_else(String::new, |f| {
                f.to_ascii_uppercase().to_string() + &c.as_str().to_ascii_lowercase()
            })
        })
        .collect()
}

/// `protocol_binding` as `protocolBinding`, as serde's `camelCase` does.
fn camel(snake: &str) -> String {
    let mut out = String::new();
    let mut upper = false;
    for c in snake.chars() {
        if c == '_' {
            upper = true;
        } else if upper {
            out.push(c.to_ascii_uppercase());
            upper = false;
        } else {
            out.push(c);
        }
    }
    out
}

/// Formats `source` with the toolchain's `rustfmt`, as `cargo fmt` would.
fn rustfmt(source: &str) -> Result<String, String> {
    use std::io::Write as _;
    use std::process::{Command, Stdio};
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--emit", "stdout"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("cannot run rustfmt: {e}"))?;
    child
        .stdin
        .take()
        .expect("stdin is piped")
        .write_all(source.as_bytes())
        .map_err(|e| format!("rustfmt stdin: {e}"))?;
    let out = child
        .wait_with_output()
        .map_err(|e| format!("rustfmt: {e}"))?;
    if !out.status.success() {
        return Err(format!(
            "rustfmt refused the generated source:\n{}\n--- source ---\n{source}",
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    String::from_utf8(out.stdout).map_err(|e| format!("rustfmt output: {e}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_translate_as_serde_and_prost_do() {
        assert_eq!(screaming("TaskState"), "TASK_STATE");
        assert_eq!(pascal("INPUT_REQUIRED"), "InputRequired");
        assert_eq!(camel("protocol_binding"), "protocolBinding");
        assert_eq!(camel("url"), "url");
    }

    #[test]
    fn escape_leaves_code_spans_alone() {
        assert_eq!(escape("a [b] `<c>` <d>"), "a \\[b\\] `<c>` \\<d\\>");
    }

    #[test]
    fn urls_become_code_spans_with_their_quotes() {
        assert_eq!(
            escape("Example: \"https://a.example/v1\", \"https://b.example\""),
            "Example: `\"https://a.example/v1\"`, `\"https://b.example\"`"
        );
        assert_eq!(escape("see `https://x` too"), "see `https://x` too");
    }
}
